function validate([edges]) {
  if (!Array.isArray(edges) || edges.length < 2 || edges.length > 100000) return 'edges needs 2 to 100000 entries.';
  for (let i = 0; i < edges.length; i++) {
    if (!Number.isInteger(edges[i]) || edges[i] < 0 || edges[i] >= edges.length) return 'Each edges[i] is a node label from 0 to n - 1.';
    if (edges[i] === i) return 'A node cannot point to itself.';
  }
  return null;
}

