function countVisitedNodes(edges) {
  const n = edges.length;
  const indegree = new Array(n).fill(0);
  for (const next of edges) {
    indegree[next]++;
  }
  const order = [];
  for (let node = 0; node < n; node++) {
    if (indegree[node] === 0) {
      order.push(node);
    }
  }
  for (let head = 0; head < order.length; head++) {
    const next = edges[order[head]];
    indegree[next]--;
    if (indegree[next] === 0) {
      order.push(next);
    }
  }
  const answer = new Array(n).fill(0);
  for (let start = 0; start < n; start++) {
    if (indegree[start] === 0 || answer[start] > 0) {
      continue;
    }
    const cycle = [start];
    for (let node = edges[start]; node !== start; node = edges[node]) {
      cycle.push(node);
    }
    for (const node of cycle) {
      answer[node] = cycle.length;
    }
  }
  for (let i = order.length - 1; i >= 0; i--) {
    const node = order[i];
    answer[node] = answer[edges[node]] + 1;
  }
  return answer;
}

