function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 8);
  const pick = i => {
    const v = Math.floor(rand() * (n - 1));
    return v >= i ? v + 1 : v;
  };
  const shape = rand();
  if (shape < 0.25) {
    // A long chain that ends in a short cycle near the end.
    const cycle = 2 + Math.floor(rand() * Math.min(5, n - 1));
    const edges = Array.from({ length: n }, (_, i) => i + 1);
    edges[n - 1] = n - cycle;
    return [edges];
  }
  if (shape < 0.45) {
    // A random permutation without fixed points: every node lies on a cycle.
    for (;;) {
      const perm = Array.from({ length: n }, (_, i) => i);
      for (let i = n - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [perm[i], perm[j]] = [perm[j], perm[i]];
      }
      if (perm.every((v, i) => v !== i)) return [perm];
    }
  }
  if (shape < 0.65) {
    // Most nodes point to a smaller label, so trees hang off a few cycles.
    const edges = Array.from({ length: n }, (_, i) => i > 0 && rand() < 0.85 ? Math.floor(rand() * i) : pick(i));
    return [edges];
  }
  return [Array.from({ length: n }, (_, i) => pick(i))];
}
